export function AppProvider({ children }) {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [language, setLanguage] = useState(() => {
    try {
      return localStorage.getItem(LANGUAGE_STORAGE_KEY) || 'en';
    } catch {
      return 'en';
    }
  });

  const toggleSidebar = useCallback(() => setSidebarCollapsed((v) => !v), []);
  const toggleMobileMenu = useCallback(() => setMobileMenuOpen((v) => !v), []);
  const closeMobileMenu = useCallback(() => setMobileMenuOpen(false), []);
  const changeLanguage = useCallback((nextLanguage) => {
    if (!LANGUAGE_OPTIONS.some((option) => option.value === nextLanguage)) return;
    setLanguage(nextLanguage);
    try {
      localStorage.setItem(LANGUAGE_STORAGE_KEY, nextLanguage);
    } catch {
      // Ignore storage failures in restricted or private browsing mode.
    }
  }, []);

  const t = useCallback((key, params = {}) => {
    const dictionary = DICTIONARY[language] || DICTIONARY.en;
    const raw = dictionary[key] || DICTIONARY.en[key] || key;
    return raw.replace(/\{(\w+)\}/g, (_, token) => params[token] ?? `{${token}}`);
  }, [language]);

  return (
    <AppContext.Provider
      value={{ sidebarCollapsed, toggleSidebar, mobileMenuOpen, toggleMobileMenu, closeMobileMenu, language, changeLanguage, t }}
    >
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used within an AppProvider');
  return ctx;
}
